INSERT INTO public.curriculum_substrands (code, subject_key, grade, strand, sub_strand, sequence, source, framework, lessons) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G', 'agriculture', 6, 'Production Techniques', 'Constructing Moist Bed Garden', 402, 'kicd_2024', 'cbc', 15) ON CONFLICT (code) DO NOTHING;
