INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION', 'agriculture', 6, 'Name the types of soil erosion and what causes them', ARRAY['AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.a']::text[], 'The child names splash erosion (raindrops knock soil loose), sheet erosion (a thin layer is washed away evenly), rill erosion (small channels cut in the soil) and gully erosion (deep channels), and names causes (heavy rain, bare ground, cutting trees, overgrazing, ploughing up and down a slope). The child does not say a gully is a thin layer. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the type from its description","say which type is the most harmful","pick a cause","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION', 'agriculture', 6, 'Pick the right way to control soil erosion on a slope', ARRAY['AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.b']::text[], 'The child names ways to control erosion (terraces and contour ploughing across the slope, planting trees, grass or cover crops, mulching, grass strips, closing a gully with stones and planting it), says each works by slowing the water or holding the soil, and does not plough up and down a slope or leave it bare. This is the knowledge half of outcome b; doing it is practical. The practical (controlling erosion on a school slope) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the control for a site","say why a control works","say which action makes erosion worse","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'AGRI.G6.CONSER.CONSERVING_WATER', 'agriculture', 6, 'Say which seedbeds keep soil moisture and how to keep a seedbed moist', ARRAY['AGRI.G6.CONSER.CONSERVING_WATER.a', 'AGRI.G6.CONSER.CONSERVING_WATER.b']::text[], 'The child says a sunken bed (a bed dug below the ground level) holds water and suits a dry place, that a raised bed drains fast and suits a very wet place, that a flat bed lies between the two, and that mulch (dry grass or leaves on the bed) keeps the soil moist. Preparing a seedbed is practical. The practical (preparing a sunken seedbed and shallow pits) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the bed for a dry place","pick the bed for a wet place","say what mulch does","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS', 'agriculture', 6, 'Pick a safe deterrent for each wild animal that raids a farm', ARRAY['AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.a']::text[], 'The child picks a deterrent that keeps the animal away without killing it (a scarecrow or shiny strips for birds, a beehive fence, a chilli fence or a trench for elephants, a thorn or live fence, noise from a tin or a guard dog), says wild animals must be kept away and not killed, and does not pick poison or a snare. Setting a deterrent up is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the deterrent for an animal","say why a deterrent works","say why the animal is not killed","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS', 'agriculture', 6, 'Say how a deterrent is put up and kept working', ARRAY['AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.b']::text[], 'Says how a chosen deterrent (mesh fence, thorny fence, light, noise maker or deflector) is put up: sited where the animals come in, built from local materials, checked and repaired, and moved or changed so animals do not get used to it; in the app the child picks the right step, order, tool or reason in new situations. The practical (establishing a deterrent in the local context) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose materials","story with a reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A', 'agriculture', 6, 'Say the routine practices in rearing rabbits and chickens', ARRAY['AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.a']::text[], 'The child says daily jobs are feeding on proper feed, giving clean water, and checking each animal, that the house is cleaned and kept dry, that animals are vaccinated and dewormed as advised, that a sick animal is separated and the adult or animal health worker is told, and that records are kept. The child does not say any scraps will do or that water is optional. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the routine job","say how often a job is done","say what a sick animal needs","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A', 'agriculture', 6, 'Say how a rabbit hutch is set up and how the animals are fed, watered and kept healthy', ARRAY['AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.b']::text[], 'Says how small animals are reared: a raised, airy, dry hutch safe from predators, fed greens and dry feed daily, clean water always, droppings removed, parasites checked, sick animals separated; in the app the child picks the right step, order, tool or reason in new situations. The practical (rearing rabbits or guinea pigs at school) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the feed","story with a reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS', 'agriculture', 6, 'Say how to dry and store crop produce at home', ARRAY['AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.a']::text[], 'The child puts the steps of drying in order (sort and wash, cut if big, spread thin on a clean raised tray in the sun, turn it, cover from dust and rain, store when crisp or hard), says dry food keeps because germs and moulds need water to grow, and that dry produce is stored in clean, dry, closed containers off the floor. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["put the drying steps in order","pick the way to store it","say why dry food keeps","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS', 'agriculture', 6, 'Say the steps of sun-drying fruits and vegetables and how to tell they are dry', ARRAY['AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.b']::text[], 'Puts the steps of sun-drying in order (choose fresh produce, wash, cut thin and even, blanch vegetables if needed, spread on a clean raised rack, cover with a net, turn, take in at night, dry until crisp or leathery, store sealed); in the app the child picks the right step, order, tool or reason in new situations. The practical (preserving fruits or vegetables by sun-drying) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose a reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'AGRI.G6.FOOD_P.COOKING_FOOD', 'agriculture', 6, 'Match a cooking method to its food and to how it cooks', ARRAY['AGRI.G6.FOOD_P.COOKING_FOOD.a']::text[], 'The child says boiling cooks in water (githeri, ugali, eggs), steaming cooks in the steam above the water, frying cooks in oil (shallow for chapati, deep for mandazi), roasting cooks with dry heat (maize on a fire) and baking cooks in an oven, and does not use water for frying. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the method for a food","say what the method uses to cook","say which method needs oil","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'AGRI.G6.FOOD_P.COOKING_FOOD', 'agriculture', 6, 'Say how to stew and how to bake by the rubbing-in method', ARRAY['AGRI.G6.FOOD_P.COOKING_FOOD.b']::text[], 'Says how to stew (cut food, fry onions lightly, add food and a little liquid, cover, simmer gently, stir now and then) and bake by rubbing in (sift flour, rub fat in with fingertips until it looks like breadcrumbs, add liquid, shape, bake in a hot oven until risen and brown); in the app the child picks the right step, order, tool or reason in new situations. The practical (cooking food by stewing and baking (rubbing-in method)) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the reason","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'AGRI.G6.HYGIEN.GOOD_GROOMING', 'agriculture', 6, 'Say the practices that keep the body clean and why', ARRAY['AGRI.G6.HYGIEN.GOOD_GROOMING.a', 'AGRI.G6.HYGIEN.GOOD_GROOMING.b']::text[], 'The child says a bath with soap every day, washing hands with soap after the toilet and before eating, brushing the teeth twice a day, keeping the nails short and clean, washing the hair, and wearing clean clothes, give reasons (they stop germs and smell), and says towels, toothbrushes and combs are not shared. The practical (practising body cleanliness as a daily habit) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the practice and how often","say why a practice matters","say what not to share","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL', 'agriculture', 6, 'Pick the right way to remove a common stain', ARRAY['AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.a']::text[], 'The child names common stains (ink, tea, grease or oil, blood, mud, fruit juice, rust) and picks a gentle first treatment (cold water and soap for blood, soap and warm water for grease, let mud dry and brush it off before washing, lemon juice and salt with sun for rust), and does not rub hard, use hot water on blood or pour harsh chemicals on cloth. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the stain from its look","pick how to treat the stain","say what not to do","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL', 'agriculture', 6, 'Say the steps of removing a blood or grass stain', ARRAY['AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.b']::text[], 'Says the steps of removing a stain: treat it while fresh, scrape off what is loose, work from the outside of the stain inwards, use cold water and salt for blood and soap or a little methylated spirit (by the teacher) for grass, rinse, check, then wash as usual; in the app the child picks the right step, order, tool or reason in new situations. The practical (removing common stains from clothing and household articles) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the treatment","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'AGRI.G6.PRODUC.CROCHETING_STITCHES', 'agriculture', 6, 'Name the basic crochet stitches, the tool and the articles made', ARRAY['AGRI.G6.PRODUC.CROCHETING_STITCHES.a']::text[], 'The child says crocheting uses one crochet hook and yarn (not two needles), that the chain stitch is the base and begins every piece, that the slip stitch joins, that the single crochet is short and the double crochet taller, and names articles made (a doily, a table mat, a coaster, a small bag). Crocheting is practical. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["name the stitch","say which stitch comes first","pick the tool","find the false step in a learner''s answer"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'AGRI.G6.PRODUC.CROCHETING_STITCHES', 'agriculture', 6, 'Say how a crocheted article is made, from slip knot to fastening off', ARRAY['AGRI.G6.PRODUC.CROCHETING_STITCHES.b']::text[], 'Says how a crocheted article is made: hold the hook and yarn, make a slip knot, a chain of the needed length, turn and work rows of single or double crochet (with the turning chain), keep the tension even, fasten off and weave in the end; in the app the child picks the right step, order, tool or reason in new situations. The practical (making a household article with crochet stitches) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["order the steps","choose the stitch","story"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G', 'agriculture', 6, 'Say what a moist bed garden is and how it is built', ARRAY['AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.a', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.b']::text[], 'The child says a moist bed garden is a sunken bed with layers of dry plant matter and manure under the topsoil and mulch on top, which holds water so that vegetables such as kale and spinach grow in dry times, puts the steps in order (choose a site near water, dig, add layers, add topsoil, plant, mulch, water), and does not say it is a raised bed. Building it is practical. The practical (constructing a moist bed garden and growing a crop) is marked by the teacher with the KICD rubric indicator; the app asks only the knowledge half. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["say what a moist bed garden is","put the building steps in order","pick the site","find the false step in a learner''s plan"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'AGRI.G5.CONSER.SOIL_CONSERVATION.a', 'outcome', 'essential', 'Grade 5 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'AGRI.G5.CONSER.SOIL_CONSERVATION.SOIL_SITES', 'skill', 'essential', 'Grade 5 picked out bare and washed sites; Grade 6 names the kind of erosion seen there. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'SCIE.G4.FORCE_.FORCE_AND_ITS_EFFECT.FORCE_EFFECTS', 'skill', 'essential', 'Raindrops and running water are forces that move soil. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'skill', 'essential', 'This skill builds on it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'AGRI.G5.CONSER.SOIL_CONSERVATION.PLANT_REMAINS', 'skill', 'essential', 'Mulching with plant remains, from Grade 5, is one way of controlling erosion. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'AGRI.G5.CONSER.WATER_CONSERVATION.a', 'outcome', 'essential', 'Grade 5 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'AGRI.G5.CONSER.WATER_CONSERVATION.WATER_WAYS', 'skill', 'essential', 'Grade 5 named ways of conserving water in a garden; sunken beds are one. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING', 'skill', 'essential', 'Preparing a seedbed was learnt in Grade 4. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.a', 'outcome', 'essential', 'Grade 5 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.REPEL_METHODS', 'skill', 'essential', 'Grade 5 chose safe repelling methods; Grade 6 names physical deterrents. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'skill', 'essential', 'The child chooses the deterrent before putting it up. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'AGRI.G5.CONSER.CONSERVING_WILD_ANIMALS.PEST_DAMAGE', 'skill', 'essential', 'Knowing where and when the animal raids tells where to put the deterrent. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.a', 'outcome', 'essential', 'Grade 5 Agriculture and Nutrition introduced it. Proposed, to confirm by a teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'AGRI.G5.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'skill', 'essential', 'Grade 5 related animals to their uses; Grade 6 rears small ones for food. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'skill', 'essential', 'The routine practices are named before they are carried out. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
