INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'AGRI.G5.PRODUC.REPAIRING_GARMENTS.STITCH_TYPES', 'skill', 'essential', 'Telling stitches apart by how they look began with running and back stitch. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
