INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'MATH.G4.MEASUR.LENGTH.MEASURE_CM', 'skill', 'essential', 'The chain is measured to the size the mat or wiper needs. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
