INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'skill', 'essential', 'Sunken beds that hold moisture (Grade 6 1.2) are the base of a moist bed garden. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES.M_AG_ER_MIX', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'Mixes up the names of the types of erosion.', '{"question":"Which erosion removes a thin layer of soil evenly?","wrong_answer":"Gully erosion","correct_answer":"Sheet erosion"}'::jsonb, 'The child knows the words but not what each looks like.', 'Offer "Gully erosion" next to the right answer and ask the question again in a new context.', 'Draw each type: sheet is a thin sheet, rill is a small channel, gully is a deep channel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES.M_AG_ER_GULLY', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'Says a gully is a thin layer or a small mark.', '{"question":"What is gully erosion?","wrong_answer":"A thin layer of soil washed away evenly","correct_answer":"Deep channels cut in the soil by running water"}'::jsonb, 'The child thinks every kind of erosion is small.', 'Offer "A thin layer of soil washed away evenly" next to the right answer and ask the question again in a new context.', 'Show a photo of a gully next to a rill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES.M_AG_ER_CAUSE', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'Names a cause that does not cause erosion, or says erosion has no human cause.', '{"question":"Which action causes soil erosion?","wrong_answer":"Planting grass on the slope","correct_answer":"Cutting down the trees on a slope"}'::jsonb, 'The child does not link bare ground with washing away.', 'Offer "Planting grass on the slope" next to the right answer and ask the question again in a new context.', 'Pour water on bare soil and on soil with grass and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL.M_AG_EC_DOWNHILL', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'Ploughs up and down a slope.', '{"question":"How should a slope be ploughed?","wrong_answer":"Up and down the slope","correct_answer":"Across the slope, along the contour"}'::jsonb, 'The child thinks straight rows are best.', 'Offer "Up and down the slope" next to the right answer and ask the question again in a new context.', 'Pour water down furrows that go up and down and across.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL.M_AG_EC_BARE', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'Leaves the ground bare or cuts the cover.', '{"question":"Which action helps control erosion?","wrong_answer":"Clearing all the plants from the slope","correct_answer":"Planting grass and trees on the slope"}'::jsonb, 'The child thinks a clean field is a good field.', 'Offer "Clearing all the plants from the slope" next to the right answer and ask the question again in a new context.', 'Compare a bare slope and a grassed slope in rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL.M_AG_EC_GRAZE', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'Thinks letting animals graze freely protects the soil.', '{"question":"How does overgrazing affect the soil?","wrong_answer":"It protects the soil with manure","correct_answer":"It leaves the ground bare so it washes away"}'::jsonb, 'The child links animals with manure only.', 'Offer "It protects the soil with manure" next to the right answer and ask the question again in a new context.', 'Look at a heavily grazed patch and a fenced patch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES.M_AG6_ER_SPLASH', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_TYPES', 'Thinks splash erosion is caused by people splashing water, not by raindrops hitting bare soil.', '{"question":"What causes splash erosion?","wrong_answer":"People splashing water about","correct_answer":"Raindrops hitting bare soil and throwing it up"}'::jsonb, 'The child takes the word "splash" from play.', 'Offer "People splashing water about" next to the right answer and ask the question again in a new context.', 'Drop water from a height on bare soil on white paper: look at the soil specks thrown up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL.M_AG6_EC_GULLY_FILL', 'AGRI.G6.CONSER.CONTROLLING_SOIL_EROSION.EROSION_CONTROL', 'Thinks a gully is controlled by filling it with rubbish and polythene.', '{"question":"How can a growing gully be controlled?","wrong_answer":"Fill it with rubbish and polythene","correct_answer":"Build checks of stones or sticks across it and plant grass"}'::jsonb, 'The child sees a hole and thinks of filling it with anything.', 'Offer "Fill it with rubbish and polythene" next to the right answer and ask the question again in a new context.', 'Show a gully with stone checks holding soil behind them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS.M_AG_SB_RAISED_DRY', 'AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'Says a raised bed is best in a dry place.', '{"question":"Which seedbed keeps moisture best in a dry place?","wrong_answer":"A raised bed","correct_answer":"A sunken bed"}'::jsonb, 'The child thinks higher means better.', 'Offer "A raised bed" next to the right answer and ask the question again in a new context.', 'Pour water on a raised and a sunken bed and watch which keeps it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS.M_AG_SB_WET', 'AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'Says a sunken bed is best in a very wet place.', '{"question":"Which seedbed suits a very wet place?","wrong_answer":"A sunken bed","correct_answer":"A raised bed"}'::jsonb, 'The child does not think about waterlogging.', 'Offer "A sunken bed" next to the right answer and ask the question again in a new context.', 'Pour a lot of water on both beds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS.M_AG_SB_BARE', 'AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'Leaves the seedbed uncovered after sowing.', '{"question":"What does mulch do on a seedbed?","wrong_answer":"Nothing, it only looks tidy","correct_answer":"It keeps the soil moist and cool"}'::jsonb, 'The child does not see water leaving the bare soil.', 'Offer "Nothing, it only looks tidy" next to the right answer and ask the question again in a new context.', 'Cover one bed with dry grass and leave one bare in the sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS.M_AG6_SB_PITMANURE', 'AGRI.G6.CONSER.CONSERVING_WATER.SEEDBEDS', 'Thinks shallow pits are dug and planted with no manure.', '{"question":"What is put in a shallow planting pit before planting?","wrong_answer":"Nothing, the pit is enough","correct_answer":"Manure or compost mixed with topsoil"}'::jsonb, 'The child thinks the pit only catches water.', 'Offer "Nothing, the pit is enough" next to the right answer and ask the question again in a new context.', 'Grow two pits, one with manure; compare after a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS.M_AG_DT_KILL', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'Says wild animals that raid crops should be killed or poisoned.', '{"question":"What should a farmer do about elephants that raid his crops?","wrong_answer":"Set poison to kill them","correct_answer":"Use a beehive fence or chilli to keep them away"}'::jsonb, 'The child thinks the only way to protect crops is to kill.', 'Offer "Set poison to kill them" next to the right answer and ask the question again in a new context.', 'Discuss why wild animals are conserved and how deterrents work.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS.M_AG_DT_WRONG', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'Picks a deterrent that does not suit the animal.', '{"question":"Which deterrent keeps birds off the crops?","wrong_answer":"A beehive fence","correct_answer":"A scarecrow or shiny strips"}'::jsonb, 'The child mixes the deterrents.', 'Offer "A beehive fence" next to the right answer and ask the question again in a new context.', 'Match each animal to what it fears.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS.M_AG_DT_SNARE', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'Says a snare or trap is a deterrent.', '{"question":"Which is a safe deterrent?","wrong_answer":"A snare set along the path","correct_answer":"Noise from a tin or a guard dog"}'::jsonb, 'The child does not tell a trap from a deterrent.', 'Offer "A snare set along the path" next to the right answer and ask the question again in a new context.', 'A deterrent keeps the animal away. A snare harms it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS.M_AG6_DT_HURT', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENTS', 'Thinks a deterrent must hurt the animal to work.', '{"question":"How does a deterrent protect crops?","wrong_answer":"By hurting or killing the animal","correct_answer":"By keeping it away without harming it"}'::jsonb, 'The child links protection with punishment.', 'Offer "By hurting or killing the animal" next to the right answer and ask the question again in a new context.', 'Ask whether a bright light at night hurts a bush pig, and what it does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP.M_AG6_DS_GAPS', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'Leaves gaps at the bottom of a mesh fence.', '{"question":"Why must the bottom of a mesh fence touch or go into the ground?","wrong_answer":"It does not matter","correct_answer":"Animals push or dig under any gap"}'::jsonb, 'The child pictures animals jumping over, not crawling under.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Show tracks under a fence gap in a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP.M_AG6_DS_ONCE', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'Thinks a deterrent put up once works for ever.', '{"question":"A solar light has kept porcupines away for a month. Now they are back. Why?","wrong_answer":"The light is broken for ever","correct_answer":"The animals got used to it; change or move it"}'::jsonb, 'The child does not know animals learn that a thing is harmless.', 'Offer "The light is broken for ever" next to the right answer and ask the question again in a new context.', 'Compare with the scarecrow from Grade 4: birds got used to it when it was not moved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP.M_AG6_DS_LIVE', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'Thinks a live thorny fence (such as kei apple or sisal) keeps animals out from the day it is planted.', '{"question":"A school plants a kei apple hedge to keep out goats and hares. When will it work?","wrong_answer":"The same day it is planted","correct_answer":"After it has grown thick, in a year or more; protect the crop meanwhile"}'::jsonb, 'The child thinks of the fence as finished once it is in the ground.', 'Offer "The same day it is planted" next to the right answer and ask the question again in a new context.', 'Show young hedge plants with wide gaps between them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP.M_AG6_DS_SITE', 'AGRI.G6.CONSER.CONSERVING_WILD_ANIMALS.DETERRENT_SETUP', 'Puts the deterrent in the middle of the farm instead of where the animals come in.', '{"question":"Where should a deflector or fence be put?","wrong_answer":"In the middle of the garden","correct_answer":"Along the path or edge where the animals come in"}'::jsonb, 'The child puts it near the crop to guard.', 'Offer "In the middle of the garden" next to the right answer and ask the question again in a new context.', 'Draw the animal paths on a farm sketch and mark where they enter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS.M_AG_SA_WATER', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'Says water is optional or only when they look thirsty.', '{"question":"How often do rabbits and chickens need clean water?","wrong_answer":"Only when they look thirsty","correct_answer":"Every day, fresh and clean"}'::jsonb, 'The child thinks they get water from the food.', 'Offer "Only when they look thirsty" next to the right answer and ask the question again in a new context.', 'Check a trough left for a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS.M_AG_SA_DIRTY', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'Leaves the house dirty and wet.', '{"question":"How should the animal house be kept?","wrong_answer":"Wet and left for weeks","correct_answer":"Clean and dry, with the droppings removed often"}'::jsonb, 'The child thinks droppings do not matter.', 'Offer "Wet and left for weeks" next to the right answer and ask the question again in a new context.', 'Discuss how dirt spreads disease.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS.M_AG_SA_SICK', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'Leaves a sick animal with the others and tells no one.', '{"question":"A chicken looks sick. What should you do?","wrong_answer":"Leave it with the others and say nothing","correct_answer":"Separate it and tell the teacher or the animal health worker"}'::jsonb, 'The child does not think disease spreads.', 'Offer "Leave it with the others and say nothing" next to the right answer and ask the question again in a new context.', 'Role play a sick chicken.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS.M_AG6_SA_EARS', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.SMALL_ANIMALS', 'Lifts a rabbit by its ears.', '{"question":"How should a rabbit be lifted?","wrong_answer":"By the ears","correct_answer":"With one hand under the chest and the other supporting the rump"}'::jsonb, 'The child has seen rabbits carried by the ears and thinks the long ears are handles.', 'Offer "By the ears" next to the right answer and ask the question again in a new context.', 'Show the correct hold on a soft toy; ask where the rabbit''s weight is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH.M_AG6_RH_FLOOR', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'Builds the hutch on the bare ground.', '{"question":"Why is a rabbit hutch raised off the ground?","wrong_answer":"It does not need to be","correct_answer":"To keep it dry and away from rats, dogs and snakes"}'::jsonb, 'The child pictures a hen house on the ground.', 'Offer "It does not need to be" next to the right answer and ask the question again in a new context.', 'Ask what happens to a hutch on the ground when it rains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH.M_AG6_RH_WETGREENS', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'Feeds rabbits wet or wilted greens straight after rain.', '{"question":"What greens should rabbits be fed?","wrong_answer":"Wet or wilted leaves","correct_answer":"Fresh greens wilted slightly in the shade, not wet"}'::jsonb, 'The child thinks wet leaves give the rabbit water too.', 'Offer "Wet or wilted leaves" next to the right answer and ask the question again in a new context.', 'Ask the teacher about bloat and runny droppings from wet greens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH.M_AG6_RH_CROWD', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'Puts many rabbits in one small hutch to save space.', '{"question":"Why should a hutch not be overcrowded?","wrong_answer":"It keeps them warm","correct_answer":"Crowded animals fight, get dirty and spread disease"}'::jsonb, 'The child thinks animals like to be together as much as possible.', 'Offer "It keeps them warm" next to the right answer and ask the question again in a new context.', 'Draw a small hutch with ten rabbits; ask what happens to the droppings and the food.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH.M_AG6_RH_PARASITE', 'AGRI.G6.FOOD_P.REARING_SMALL_DOMESTIC_A.REARING_HUTCH', 'Thinks scratching and hair loss in a rabbit are normal.', '{"question":"A rabbit scratches a lot and has bare patches. What should be done?","wrong_answer":"Nothing, rabbits do that","correct_answer":"Check for mites, separate it and ask an adult or vet for treatment"}'::jsonb, 'The child does not know small animals get parasites.', 'Offer "Nothing, rabbits do that" next to the right answer and ask the question again in a new context.', 'Show a picture of mange on a rabbit''s ear.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE.M_AG_PR_WET', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE', 'Stores produce before it is dry.', '{"question":"When may dried maize be stored?","wrong_answer":"When it is still damp","correct_answer":"When it is fully dry and hard"}'::jsonb, 'The child thinks drying is only for the sun.', 'Offer "When it is still damp" next to the right answer and ask the question again in a new context.', 'Store one damp and one dry sample and see which grows mould.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE.M_AG_PR_FLOOR', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE', 'Stores produce on the floor or in an open container.', '{"question":"Where should dry produce be stored?","wrong_answer":"On the floor in an open sack","correct_answer":"In a clean closed container, off the floor"}'::jsonb, 'The child does not think of damp and pests.', 'Offer "On the floor in an open sack" next to the right answer and ask the question again in a new context.', 'Compare a sack on the floor and one on a pallet.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE.M_AG_PR_WHY', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE', 'Says dry food keeps because the sun kills everything for ever.', '{"question":"Why does dry food keep longer?","wrong_answer":"The sun makes it harmless for ever","correct_answer":"Germs and moulds need water to grow"}'::jsonb, 'The child thinks the sun is a permanent cure.', 'Offer "The sun makes it harmless for ever" next to the right answer and ask the question again in a new context.', 'Add water to dried food and watch it spoil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE.M_AG6_PR_WHOLE', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.PRESERVE', 'Thinks whole fruits dry as well as thin slices.', '{"question":"Why are mangoes cut into thin slices for drying?","wrong_answer":"It makes no difference","correct_answer":"Thin slices dry quickly before they rot"}'::jsonb, 'The child does not link thickness with drying time.', 'Offer "It makes no difference" next to the right answer and ask the question again in a new context.', 'Dry a thick and a thin slice side by side for two days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS.M_AG6_DRY_GROUND', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS', 'Spreads the produce on the bare ground or a dusty sack.', '{"question":"Where should vegetables be spread for drying?","wrong_answer":"On the bare ground","correct_answer":"On a clean raised rack or tray, covered with a net"}'::jsonb, 'The child has seen grain dried on the ground and copies it.', 'Offer "On the bare ground" next to the right answer and ask the question again in a new context.', 'Ask what reaches food on the ground: dust, chickens, insects.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS.M_AG6_DRY_UNEVEN', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS', 'Cuts pieces of very different thickness and expects them to dry together.', '{"question":"Why are slices for drying cut the same thickness?","wrong_answer":"It only looks neater","correct_answer":"So they all dry at the same time and none stays wet"}'::jsonb, 'The child thinks cutting is only about size, not drying time.', 'Offer "It only looks neater" next to the right answer and ask the question again in a new context.', 'Dry a thick and a thin slice on the same tray and feel both after a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS.M_AG6_DRY_NIGHT', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS', 'Leaves the drying produce out overnight.', '{"question":"What should be done with drying produce in the evening?","wrong_answer":"Leave it out all night","correct_answer":"Take it in or cover it, because the night air is damp"}'::jsonb, 'The child thinks drying goes on all the time.', 'Offer "Leave it out all night" next to the right answer and ask the question again in a new context.', 'Touch a slice left out overnight: it is damp again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS.M_AG6_DRY_SOFT', 'AGRI.G6.FOOD_P.PRESERVING_CROP_PRODUCTS.DRYING_STEPS', 'Stores the produce while it is still soft and moist inside.', '{"question":"How do you know dried sukuma wiki is ready to store?","wrong_answer":"It has been in the sun one day","correct_answer":"It is crisp and breaks easily"}'::jsonb, 'The child counts days instead of testing the food.', 'Offer "It has been in the sun one day" next to the right answer and ask the question again in a new context.', 'Break a crisp and a limp leaf.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG_CK_MIX', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Mixes up the methods and what they use.', '{"question":"Which method cooks food in oil?","wrong_answer":"Boiling","correct_answer":"Frying"}'::jsonb, 'The child knows the words but not what each uses.', 'Offer "Boiling" next to the right answer and ask the question again in a new context.', 'Name what each method uses: water, steam, oil, dry heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG_CK_FOOD', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Picks the wrong method for a food.', '{"question":"Which method is used for githeri?","wrong_answer":"Roasting","correct_answer":"Boiling"}'::jsonb, 'The child does not link the food with how it is cooked.', 'Offer "Roasting" next to the right answer and ask the question again in a new context.', 'List five foods and the way each is cooked at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG_CK_STEAM', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Says steaming cooks in the water itself.', '{"question":"In steaming, what cooks the food?","wrong_answer":"The boiling water the food sits in","correct_answer":"The steam above the water"}'::jsonb, 'The child mixes boiling and steaming.', 'Offer "The boiling water the food sits in" next to the right answer and ask the question again in a new context.', 'Compare food in the water and food above it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG6_CK_STEW', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks stewing means boiling food fast in lots of water.', '{"question":"How is food stewed?","wrong_answer":"Boiled fast in lots of water","correct_answer":"Cooked slowly in a little liquid in a covered pan"}'::jsonb, 'The child mixes stewing with boiling because both use liquid.', 'Offer "Boiled fast in lots of water" next to the right answer and ask the question again in a new context.', 'Compare a pan of fast-boiling water with a gently simmering stew.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG6_CP_RUBPALMS', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Rubs the fat into flour with the palms, so it melts and goes greasy.', '{"question":"How is fat rubbed into flour?","wrong_answer":"With the palms, pressing hard","correct_answer":"Lightly with cool fingertips, lifting the flour"}'::jsonb, 'The child thinks more hand contact mixes better.', 'Offer "With the palms, pressing hard" next to the right answer and ask the question again in a new context.', 'Feel how warm the palm is compared with the fingertips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG6_CP_OPEN', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Keeps opening the oven to check the scones.', '{"question":"Why should the oven door not be opened often while baking?","wrong_answer":"It helps the scones cook","correct_answer":"Heat escapes and the scones may sink"}'::jsonb, 'The child wants to watch and does not think of heat escaping.', 'Offer "It helps the scones cook" next to the right answer and ask the question again in a new context.', 'Compare with the lid on a cooking pot from Grade 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG6_CP_STEWFAST', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Cooks a stew on a high flame so it is ready quickly.', '{"question":"What heat is used for stewing?","wrong_answer":"A high flame","correct_answer":"Low heat, simmering gently"}'::jsonb, 'The child thinks a big flame always cooks better.', 'Offer "A high flame" next to the right answer and ask the question again in a new context.', 'Show meat stewed fast (tough, burnt at the bottom) and slow (soft).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG6_CP_NOSIFT', 'AGRI.G6.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Pours the flour straight from the packet without sifting.', '{"question":"Why is flour sifted before baking?","wrong_answer":"It is not needed","correct_answer":"To remove lumps and add air so the scones are light"}'::jsonb, 'The child thinks sifting is only for cleaning flour.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Bake two scones, one with sifted flour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS.M_AG_BC_SOAP', 'AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'Says water alone is enough to wash hands.', '{"question":"How should hands be washed?","wrong_answer":"With water only, quickly","correct_answer":"With soap and water, after the toilet and before eating"}'::jsonb, 'The child thinks looking clean is clean.', 'Offer "With water only, quickly" next to the right answer and ask the question again in a new context.', 'Compare hands washed with soap and without.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS.M_AG_BC_TEETH', 'AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'Says teeth need brushing once a week.', '{"question":"How often should teeth be brushed?","wrong_answer":"Once a week","correct_answer":"Twice a day"}'::jsonb, 'The child thinks brushing is only for visitors.', 'Offer "Once a week" next to the right answer and ask the question again in a new context.', 'Show the plaque with a disclosing tablet if available.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS.M_AG_BC_SHARE', 'AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'Says it is fine to share a towel or a toothbrush.', '{"question":"Which item should not be shared?","wrong_answer":"A toothbrush","correct_answer":"A school desk"}'::jsonb, 'The child sees sharing as kind.', 'Offer "A toothbrush" next to the right answer and ask the question again in a new context.', 'Discuss how germs pass on a shared toothbrush.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS.M_AG6_BC_PIMPLE', 'AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'Squeezes pimples to make them go away faster.', '{"question":"What should you do about pimples?","wrong_answer":"Squeeze them","correct_answer":"Wash the face gently twice a day and leave them alone"}'::jsonb, 'The child thinks removing the pus heals the pimple.', 'Offer "Squeeze them" next to the right answer and ask the question again in a new context.', 'Explain that squeezing pushes germs deeper and can leave scars.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS.M_AG6_BC_SWEAT', 'AGRI.G6.HYGIEN.GOOD_GROOMING.BODY_CLEANLINESS', 'Thinks sweat smells bad because it is dirty in itself, so covers it with perfume instead of washing.', '{"question":"Why does sweat start to smell?","wrong_answer":"Sweat is dirty, so perfume fixes it","correct_answer":"Germs on unwashed skin break the sweat down; bathing removes them"}'::jsonb, 'The child sees the smell as coming straight from sweat.', 'Offer "Sweat is dirty, so perfume fixes it" next to the right answer and ask the question again in a new context.', 'Fresh sweat after games hardly smells; stale sweat on unwashed clothes does.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS.M_AG_ST_BLOOD', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS', 'Washes a blood stain in hot water.', '{"question":"How should a fresh blood stain be treated first?","wrong_answer":"Hot water","correct_answer":"Cold water and soap"}'::jsonb, 'The child thinks hot water cleans best.', 'Offer "Hot water" next to the right answer and ask the question again in a new context.', 'Test hot and cold water on a safe stain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS.M_AG_ST_RUB', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS', 'Rubs a stain hard so that it spreads.', '{"question":"How should a stain be treated?","wrong_answer":"Rub it hard in a circle","correct_answer":"Treat it gently from the outside to the middle"}'::jsonb, 'The child thinks harder rubbing cleans better.', 'Offer "Rub it hard in a circle" next to the right answer and ask the question again in a new context.', 'Try both on a safe cloth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS.M_AG_ST_MATCH', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS', 'Picks the wrong treatment for the stain.', '{"question":"How is a grease stain on clothes treated?","wrong_answer":"Cold water only","correct_answer":"Soap and warm water"}'::jsonb, 'The child uses one treatment for every stain.', 'Offer "Cold water only" next to the right answer and ask the question again in a new context.', 'Match each stain to the right treatment.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS.M_AG6_ST_LATER', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAINS', 'Leaves a stain to be removed on washing day.', '{"question":"When is a stain easiest to remove?","wrong_answer":"On washing day, a week later","correct_answer":"At once, while it is fresh"}'::jsonb, 'The child thinks all dirt comes out in the wash.', 'Offer "On washing day, a week later" next to the right answer and ask the question again in a new context.', 'Compare a fresh grass stain with one left for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS.M_AG6_SS_OUTSIDE', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS', 'Rubs from the middle of the stain outwards.', '{"question":"Which way should a stain be worked?","wrong_answer":"From the middle outwards","correct_answer":"From the outside edge towards the middle"}'::jsonb, 'The child starts where the stain is darkest.', 'Offer "From the middle outwards" next to the right answer and ask the question again in a new context.', 'Rub a wet ink-like stain both ways on paper: one spreads it wider.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS.M_AG6_SS_SCRAPE', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS', 'Rubs wet mud or food into the cloth before lifting off the loose part.', '{"question":"What is done first to a lump of food or mud on a shirt?","wrong_answer":"Rub it in with water","correct_answer":"Scrape or lift off the loose part first"}'::jsonb, 'The child goes straight to washing.', 'Offer "Rub it in with water" next to the right answer and ask the question again in a new context.', 'Rub a dab of porridge on a scrap with water, and scrape another first; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS.M_AG6_SS_IRON', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS', 'Irons the cloth before checking the stain is gone.', '{"question":"Why check that a stain has gone before ironing or drying in the sun?","wrong_answer":"There is no need","correct_answer":"Heat sets the stain so it never comes out"}'::jsonb, 'The child thinks ironing is the last step whatever happens.', 'Offer "There is no need" next to the right answer and ask the question again in a new context.', 'Iron a faint stain on a scrap and try to wash it again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS.M_AG6_SS_SALT', 'AGRI.G6.HYGIEN.LAUNDRY_STAIN_REMOVAL.STAIN_STEPS', 'Does not know salt water helps lift a fresh blood stain.', '{"question":"What helps remove a fresh blood stain?","wrong_answer":"Hot water and hard rubbing","correct_answer":"Soaking in cold salty water, then washing"}'::jsonb, 'The child knows only soap and water for stains.', 'Offer "Hot water and hard rubbing" next to the right answer and ask the question again in a new context.', 'Soak a blood-stained scrap in cold salt water and another in hot water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET.M_AG_CR_NEEDLE', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'Says crocheting uses two knitting needles.', '{"question":"What is used to crochet?","wrong_answer":"Two knitting needles","correct_answer":"One crochet hook and yarn"}'::jsonb, 'The child mixes crocheting and knitting.', 'Offer "Two knitting needles" next to the right answer and ask the question again in a new context.', 'Show the hook and two needles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET.M_AG_CR_STITCH', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'Mixes up which stitch comes first.', '{"question":"Which stitch is the base of a crocheted piece?","wrong_answer":"Double crochet","correct_answer":"The chain stitch"}'::jsonb, 'The child does not know the order.', 'Offer "Double crochet" next to the right answer and ask the question again in a new context.', 'Start a piece with a chain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET.M_AG_CR_HEIGHT', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'Says single crochet is taller than double crochet.', '{"question":"Which stitch is taller?","wrong_answer":"Single crochet","correct_answer":"Double crochet"}'::jsonb, 'The child mixes the names.', 'Offer "Single crochet" next to the right answer and ask the question again in a new context.', 'Crochet a row of each and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET.M_AG6_CR_ARTICLE', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET', 'Thinks crochet makes only clothes, not household articles.', '{"question":"Which household article can be crocheted?","wrong_answer":"Only a sweater","correct_answer":"A table mat, a cleaning rug or a surface wiper"}'::jsonb, 'The child has seen crocheted clothes only.', 'Offer "Only a sweater" next to the right answer and ask the question again in a new context.', 'Show a crocheted mat and a kitchen wiper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS.M_AG6_CS_TURN', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'Forgets the turning chain at the end of a row, so the edges slope in.', '{"question":"Why is a turning chain made at the end of each row?","wrong_answer":"It is not needed","correct_answer":"To lift the yarn to the height of the next row so the edges stay straight"}'::jsonb, 'The child sees the chain as an extra stitch to skip.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Show a square with turning chains and one without; compare the edges.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS.M_AG6_CS_COUNT', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'Does not count the chain, so the mat comes out the wrong size or crooked.', '{"question":"Why count the stitches in the first chain?","wrong_answer":"It is not needed","correct_answer":"The chain sets the width of the article; every row then has the same number"}'::jsonb, 'The child crochets until it looks long enough.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Compare two wipers: one counted, one not; measure the widths of the rows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS.M_AG6_CS_TIGHT', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'Pulls every stitch very tight to make the work strong.', '{"question":"What happens if crochet stitches are pulled too tight?","wrong_answer":"The work is stronger","correct_answer":"The hook cannot go in and the article curls"}'::jsonb, 'The child thinks tight means strong, as with knots.', 'Offer "The work is stronger" next to the right answer and ask the question again in a new context.', 'Try to push the hook into a very tight chain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS.M_AG6_CS_CUT', 'AGRI.G6.PRODUC.CROCHETING_STITCHES.CROCHET_STEPS', 'Cuts the yarn at the end without pulling it through the last loop.', '{"question":"How is crochet finished?","wrong_answer":"Cut the yarn and leave it","correct_answer":"Cut, pull the end through the last loop and weave it in"}'::jsonb, 'The child thinks cutting ends the work.', 'Offer "Cut the yarn and leave it" next to the right answer and ask the question again in a new context.', 'Pull a finished piece cut without fastening: it unravels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED.M_AG_MB_RAISED', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'Says a moist bed garden is a raised bed.', '{"question":"What is a moist bed garden?","wrong_answer":"A raised bed above the ground","correct_answer":"A sunken bed that holds water"}'::jsonb, 'The child mixes the two beds.', 'Offer "A raised bed above the ground" next to the right answer and ask the question again in a new context.', 'Dig and water a sunken bed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED.M_AG_MB_ORDER', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'Puts the steps in the wrong order.', '{"question":"What comes first in building a moist bed garden?","wrong_answer":"Plant the seedlings","correct_answer":"Choose a site near water and dig"}'::jsonb, 'The child jumps to planting.', 'Offer "Plant the seedlings" next to the right answer and ask the question again in a new context.', 'Write the steps on cards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED.M_AG_MB_NOMULCH', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'Leaves out the mulch.', '{"question":"What goes on top of a moist bed garden?","wrong_answer":"Nothing","correct_answer":"Mulch such as dry grass"}'::jsonb, 'The child does not see water leaving the soil.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Compare a mulched and an unmulched bed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED.M_AG6_MB_HOLES', 'AGRI.G6.PRODUC.CONSTRUCTING_MOIST_BED_G.MOIST_BED', 'Makes holes in the bottom of the polythene lining.', '{"question":"Where are the holes in a moist bed lining made?","wrong_answer":"In the bottom, so water drains","correct_answer":"Near the top only, so water collects below and too much can escape"}'::jsonb, 'The child copies the drainage holes of a sack garden.', 'Offer "In the bottom, so water drains" next to the right answer and ask the question again in a new context.', 'Fill a lined tray with holes in the bottom and one with holes near the top; water both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
